  'content.lenormand.3.keyword.0': 'Viaje',
  'content.lenormand.3.keyword.1': 'Distancia',
  'content.lenormand.3.keyword.2': 'Comercio',
  'content.lenormand.3.meaning': 'Movimiento a través de la distancia: viajes, comercio o un anhelo que te atrae hacia algo lejano.',
  'content.lenormand.3.combination.0': 'Con el ancla, el viaje termina en puerto seguro.',
  'content.lenormand.3.combination.1': 'Con el Jinete se anuncia un viaje.',
  'content.lenormand.3.combination.2': 'Con la Montaña el viaje se retrasa.',
  'content.lenormand.3.timing': 'Distante - en tránsito',
  'content.lenormand.2.name': 'Trébol',
  'content.lenormand.2.keyword.0': 'Suerte',
  'content.lenormand.2.keyword.1': 'Oportunidad',
  'content.lenormand.2.keyword.2': 'Ligereza',
  'content.lenormand.2.meaning': 'Un pequeño golpe de suerte y un corazón más alegre: aprovecha el momento mientras la puerta permanece abierta.',
  'content.lenormand.2.combination.0': 'Con el Sol, la suerte se convierte en éxito.',
  'content.lenormand.2.combination.1': 'Con los Ratones, la suerte se te escapa si esperas.',
  'content.lenormand.2.combination.2': 'Con el Jinete las buenas noticias llegan por casualidad.',
  'content.lenormand.2.timing': 'Ahora, la ventana es breve.',
  'content.lenormand.1.name': 'Jinete',
  'content.lenormand.1.keyword.0': 'Noticias',
  'content.lenormand.1.keyword.1': 'Llegada',
  'content.lenormand.1.keyword.2': 'Movimiento',
  'content.lenormand.1.meaning': 'Las noticias y el impulso llegan: un mensaje, un visitante o un nuevo impulso que pone las cosas en movimiento.',
  'content.lenormand.1.combination.0': 'Con la Carta, el mensaje llega por escrito.',
  'content.lenormand.1.combination.1': 'Con Clover, las noticias de suerte llegan rápidamente.',
  'content.lenormand.1.combination.2': 'Con el Barco llegan noticias de muy lejos.',
  'content.lenormand.1.timing': 'Pronto: días, no semanas',
