  'content.rune.11.lore': 'La runa de la cosecha: el año del agricultor, donde nada madura antes de su mes.',
  'content.rune.10.name': 'isa',
  'content.rune.10.keyword.0': 'Hielo',
  'content.rune.10.keyword.1': 'Quietud',
  'content.rune.10.keyword.2': 'Paciencia',
  'content.rune.10.upright': 'Hielo: una pausa congelada en la que nada se mueve y todo espera.',
  'content.rune.10.lore': 'La runa del río helado: quietud tan profunda que se convierte en su propia estación.',
