  'content.rune.3.lore': 'La runa del aliento del Padre de Todo: poesía, runas y consejos de los mayores.',
  'content.rune.3.merkstave': 'Mentiras, malos consejos o palabras que sobrepasan su significado.',
  'content.rune.2.name': 'Thurisaz',
  'content.rune.2.keyword.0': 'Gigante',
  'content.rune.2.keyword.1': 'Espina',
  'content.rune.2.keyword.2': 'Defensa',
